class region;

class region_node
{
  region *data;
public:
  region *get_data() const { return data; }
};

struct region_tree_node
{
  int color;
  region_tree_node *parent;
  region_tree_node *left;
  region_tree_node *right;
  region_node *value;
};

class region_node_pset_iterator
{
  region_tree_node *node;
public:
  region_node_pset_iterator(region_tree_node *n) : node(n) {}
  region_node *operator*() const { return node->value; }
  bool operator!=(const region_node_pset_iterator& i) const { return node != i.node; }
  region_node_pset_iterator& operator++()
  {
    if (node->right != 0)
    {
      node = node->right;
      while (node->left != 0)
        node = node->left;
    }
    else
    {
      region_tree_node *y = node->parent;
      while (node == y->right)
      {
        node = y;
        y = y->parent;
      }
      if (node->right != y)
        node = y;
    }
    return *this;
  }
  region_node_pset_iterator operator++(int)
  {
    region_node_pset_iterator tmp = *this;
    ++*this;
    return tmp;
  }
};

class region_node_pset
{
  region_tree_node *header;
  unsigned int node_count;
  void _M_erase(region_tree_node *);
public:
  typedef region_node_pset_iterator iterator;
  iterator begin() { return iterator(header->left); }
  iterator end() { return iterator(header); }
  void clear()
  {
    if (node_count != 0)
    {
      _M_erase(header->parent);
      header->left = header;
      header->parent = 0;
      header->right = header;
      node_count = 0;
    }
  }
};

class entity
{
  char padding[0x160];
  region_node_pset in_regions;
public:
  virtual void remove_me_from_region(region *r);
  void remove_from_regions();
};

void entity::remove_from_regions()
{
#ifndef REGIONCULL
 	for ( region_node_pset::iterator i=in_regions.begin(); i!=in_regions.end(); i++ )
    remove_me_from_region( (*i)->get_data() );
  in_regions.clear();
#endif
}
